package dev.cheeseowl.gmbg;

import org.junit.Test;
import java.util.ArrayList;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.Assert.*;

public class BrowserTest {
    private static final String VIEW="android.intent.action.VIEW";
    private boolean allow(String uri,String id){return WebPolicy.allows(VIEW,uri,uri,id,false,false,null,false);}
    @Test public void ordinaryEncodedUrlAcceptedWithoutChangingItsText(){String url="https://www.bing.com/search?q=a%2Bb%20c&x=%E6%B5%8B%E8%AF%95#part";assertTrue(allow(url,"bing"));assertEquals("https://www.bing.com/search?q=a%2Bb%20c&x=%E6%B5%8B%E8%AF%95#part",url);}
    @Test public void allExistingOrdinaryEnginesCanQualify(){for(String id:java.util.List.of("baidu","google","custom","my-engine","另一个引擎"))assertTrue(allow("https://example.org/search?q=demo",id));assertTrue(allow("http://example.org/s?q=demo","bing"));}
    @Test public void aiOneSearchAndDedicatedPathsRemainOriginal(){assertFalse(allow("https://example.org/search?q=x","aisearch"));assertFalse(allow("https://example.org/search?q=x","onesearch"));assertFalse(allow("https://example.org/aiSearch/?q=x","bing"));assertFalse(allow("https://example.org/%61iSearch/?q=x","bing"));assertFalse(allow("https://example.org/OneSearch/?q=x","bing"));}
    @Test public void nonWebAndPendingIntentLikeSchemesAreRejected(){for(String url:java.util.List.of("mi://search?q=x","market://details?id=x","intent://search","tel:123","file:///tmp/x","content://private/x","javascript:alert(1)"))assertFalse(allow(url,"bing"));}
    @Test public void unknownOrAlreadyExplicitBranchIsSkipped(){String u="https://example.org/";assertFalse(WebPolicy.allows("android.intent.action.SEARCH",u,u,"bing",false,false,null,false));assertFalse(WebPolicy.allows(VIEW,u,u,"bing",true,false,null,false));assertFalse(WebPolicy.allows(VIEW,u,u,"bing",false,true,null,false));assertFalse(WebPolicy.allows(VIEW,u,u,"bing",false,false,"my.other.browser",false));assertFalse(WebPolicy.allows(VIEW,u,u,"bing",false,false,null,true));}
    @Test public void xiaomiDefaultIsNotExcludedByPolicy(){String u="https://example.org/";assertTrue(WebPolicy.allows(VIEW,u,u,"bing",false,false,"com.android.browser",false));}
    @Test public void missingEngineOrMismatchedBuiltUrlIsSkipped(){String u="https://example.org/";assertFalse(allow(u,null));assertFalse(WebPolicy.allows(VIEW,u,u+"?different", "bing",false,false,null,false));}
    @Test public void malformedOpaqueCredentialsWhitespaceAndPortsAreRejected(){for(String u:java.util.List.of("https:","https:opaque","https:///search","https://user:pass@example.org/","https://example.org:99999/","https://exa mple.org/","https://example.org/\nprivate","https://example.org/?q=%ZZ"))assertFalse(u,allow(u,"bing"));}
    @Test public void normalStartSuppressesOnlyOriginalBusinessCall() throws Throwable {BrowserDispatcher b=new BrowserDispatcher();AtomicInteger launched=new AtomicInteger(),original=new AtomicInteger();ArrayList<BrowserDispatcher.Outcome> logs=new ArrayList<>();Object value=b.run(true,launched::incrementAndGet,()->{original.incrementAndGet();return new Object();},logs::add);assertNull(value);assertEquals(1,launched.get());assertEquals(0,original.get());assertEquals(java.util.List.of(BrowserDispatcher.Outcome.START_REQUESTED),logs);}
    @Test public void launchFailureCallsUnchangedOriginalOnce() throws Throwable {BrowserDispatcher b=new BrowserDispatcher();AtomicInteger attempts=new AtomicInteger(),original=new AtomicInteger();Object expected=new Object();Object got=b.run(true,()->{attempts.incrementAndGet();throw new SecurityException("private URL");},()->{original.incrementAndGet();return expected;},o->{});assertSame(expected,got);assertEquals(1,attempts.get());assertEquals(1,original.get());}
    @Test public void skippedOriginalExceptionIdentityIsPreserved(){BrowserDispatcher b=new BrowserDispatcher();AtomicInteger starts=new AtomicInteger();Error expected=new Error("target");try{b.run(false,starts::incrementAndGet,()->{throw expected;},o->{});fail();}catch(Throwable got){assertSame(expected,got);}assertEquals(0,starts.get());}
    @Test public void fallbackOriginalExceptionIdentityIsPreserved(){BrowserDispatcher b=new BrowserDispatcher();Error expected=new Error("target");try{b.run(true,()->{throw new RuntimeException("launch");},()->{throw expected;},o->{});fail();}catch(Throwable got){assertSame(expected,got);}}
    @Test public void guardPreventsRecursiveReplacementAndIsReleased() throws Throwable {BrowserDispatcher b=new BrowserDispatcher();AtomicInteger launches=new AtomicInteger(),original=new AtomicInteger();b.run(true,()->{launches.incrementAndGet();b.run(true,()->launches.incrementAndGet(),()->{original.incrementAndGet();return null;},o->{});},()->{original.incrementAndGet();return null;},o->{});assertEquals(1,launches.get());assertEquals(1,original.get());b.run(true,()->launches.incrementAndGet(),()->null,o->{});assertEquals(2,launches.get());}
    @Test public void logFailureDoesNotStartOriginalAfterSuccessfulReplacement() throws Throwable {AtomicInteger original=new AtomicInteger();new BrowserDispatcher().run(true,()->{},()->{original.incrementAndGet();return null;},o->{throw new Error("log");});assertEquals(0,original.get());}
    @Test public void featureFlagsHaveAllFourIndependentCombinations(){for(boolean engine:new boolean[]{false,true})for(boolean browser:new boolean[]{false,true}){FeatureState s=FeatureState.checked(engine,browser,true);assertEquals(engine,s.engine());assertEquals(browser,s.browser());assertTrue(s.valid());}assertFalse(FeatureState.checked(true,true,false).engine());assertFalse(FeatureState.unavailable().browser());}
}
